	if generic != len(items) {
		t.Fatalf("resources count = %d, want %d (savepoint rollback must not undo generic insert)", generic, len(items))
	}

	var typed int
	typedQuery := fmt.Sprintf(`SELECT COUNT(*) FROM "%s"`, "ad_groups")
	if err := db.QueryRow(typedQuery).Scan(&typed); err != nil {
		t.Fatalf("count ad_groups: %v", err)
	}
	if typed != 0 {
		t.Fatalf("ad_groups count = %d, want 0 (typed insert violated NOT NULL on %q)", typed, "ad_accounts_id")
	}
